from modele import *
from donnees_figures import triangle,schema

def P(i,titre,enonce,corrige,methode,controle,valeurs,droit=True):
    return E(titre,enonce,corrige,methode,controle,figure=triangle(f'pyth-{i:02}',valeurs=valeurs,droit=droit))

chapitre(12,'pythagore','Pythagore et distances','4 · Géométrie',
'Triangles rectangles · Réciproque · Distances · Modélisation',
['Calculer une longueur dans un triangle rectangle.','Prouver ou réfuter qu’un triangle est rectangle.','Construire un modèle de distance.'],['Carrés, racines carrées et unités de longueur.'],[
r'''\essSection{1}{Calculer une longueur}
\begin{propriete}[Théorème de Pythagore]Si ABC est rectangle en A, alors $BC^2=AB^2+AC^2$. BC, opposé à l’angle droit, est l’hypoténuse et le plus long côté.\end{propriete}
\begin{savoirfaire}[Chercher l’hypoténuse]Pour $AB=6$ cm et $AC=8$ cm, $BC^2=36+64=100$, donc $BC=\sqrt{100}=10$ cm. Une longueur est positive : on ne retient pas $-10$.\end{savoirfaire}
\begin{savoirfaire}[Chercher un côté de l’angle droit]Si $BC=13$ cm et $AB=5$ cm, $AC^2=BC^2-AB^2=169-25=144$, d’où $AC=12$ cm.\end{savoirfaire}
\begin{attention}Le théorème exige un angle droit connu. Une apparence de dessin ne suffit pas. Lorsqu’une racine n’est pas entière, conserver la valeur exacte puis arrondir à la précision demandée.\end{attention}''',
r'''\essSection{2}{Décider et modéliser}
\begin{propriete}[Réciproque]Dans un triangle, si le carré du plus grand côté égale la somme des carrés des deux autres, alors le triangle est rectangle. L’angle droit est opposé au plus grand côté.\end{propriete}
\begin{propriete}[Contraposée]Si cette égalité n’est pas vérifiée, le triangle n’est pas rectangle. Écrire séparément les deux calculs permet une comparaison claire.\end{propriete}
\begin{savoirfaire}[Une distance dans un repère orthonormé]Entre deux points, construire un triangle rectangle avec un segment horizontal et un segment vertical. Leurs longueurs sont les écarts d’abscisses et d’ordonnées. Appliquer Pythagore. Un repère non orthonormé ne permet pas ce calcul direct.\end{savoirfaire}
\begin{savoirfaire}[Un problème concret]Identifier les points, préciser les verticales et horizontales, dessiner l’angle droit puis traduire les dimensions. Vérifier que la réponse correspond bien à la longueur demandée et reste cohérente avec les autres côtés.\end{savoirfaire}'''],[
P(1,'Reconnaître l’hypoténuse',r"ABC est rectangle en A. Nommer l’hypoténuse et écrire l’égalité de Pythagore.",r"Le côté opposé à A est $\res{BC}$. L’égalité est $\res{BC^2=AB^2+AC^2}$. Le nom du sommet rectangle détermine le bon côté.","Repérer d’abord le sommet de l’angle droit.","assert 3**2+4**2==5**2",('','','')),
P(2,'Un triangle classique',r"ABC est rectangle en A, avec AB = 6 cm et AC = 8 cm. Calculer BC.",r"Pythagore donne $BC^2=6^2+8^2=100$. Comme BC est positive, $\res{BC=10\text{ cm}}$.","Additionner les carrés pour trouver l’hypoténuse.","assert 6**2+8**2==10**2",('6 cm','8 cm','?')),
P(3,'Le côté manquant',r"ABC est rectangle en A. BC = 13 cm et AB = 5 cm. Calculer AC.",r"$AC^2=13^2-5^2=144$, donc $\res{AC=12\text{ cm}}$. AC est inférieure à l’hypoténuse 13 cm.","Isoler le carré inconnu avant d’extraire la racine.","assert 13**2-5**2==12**2",('5 cm','?','13 cm')),
P(4,'Garder une racine',r"ABC est rectangle en A. AB = 4 cm, AC = 7 cm. Donner BC exactement puis au dixième.",r"$BC^2=16+49=65$, donc $\res{BC=\sqrt{65}\text{ cm}}\approx\res{8{,}1\text{ cm}}$. L’arrondi n’est pas une égalité exacte.","Arrondir uniquement le résultat final.","assert round(math.sqrt(65),1)==8.1",('4 cm','7 cm','?')),
P(5,'Tester la réciproque',r"Dans ABC, AB = 9 cm, AC = 12 cm et BC = 15 cm. Le triangle est-il rectangle ?",r"BC est le plus grand côté. $15^2=225$ et $9^2+12^2=225$. Par la réciproque, ABC est $\res{\text{rectangle en A}}$.","Comparer les deux membres séparément.","assert 9**2+12**2==15**2",('9 cm','12 cm','15 cm'),False),
P(6,'Refuser une fausse égalité',r"AB = 5 cm, AC = 7 cm et BC = 9 cm. ABC est-il rectangle ?",r"$BC^2=81$ alors que $AB^2+AC^2=25+49=74$. Ces nombres diffèrent ; par la contraposée, $\res{\text{ABC n’est pas rectangle}}$.","Une égalité approchée ne suffit pas.","assert 5**2+7**2!=9**2",('5 cm','7 cm','9 cm'),False),
P(7,'Une échelle contre un mur',r"Le mur AC est vertical et le sol AB horizontal. Une échelle BC de 5 m est posée à 1,4 m du mur. Quelle hauteur AC atteint-elle ?",r"ABC est rectangle en A. $AC^2=5^2-1{,}4^2=23{,}04$, donc $\res{AC=4{,}8\text{ m}}$. La hauteur reste inférieure à la longueur de l’échelle.","Justifier l’angle droit par le mur et le sol.","assert Rational(5)**2-Rational('1.4')**2==Rational('4.8')**2",('1,4 m','?','5 m')),
P(8,'Diagonale d’un rectangle',r"Les côtés perpendiculaires d’un rectangle mesurent 15 cm et 20 cm. ABC en représente une moitié. Calculer la diagonale BC et le périmètre du rectangle.",r"$BC^2=15^2+20^2=625$, donc la diagonale vaut $\res{25\text{ cm}}$. Le périmètre du rectangle est $2(15+20)=\res{70\text{ cm}}$. Il ne faut pas y ajouter la diagonale intérieure.","Séparer longueur intérieure et contour.","assert 15**2+20**2==25**2 and 2*(15+20)==70",('20 cm','15 cm','?')),
E('Deux points du plan',r"Dans un repère orthonormé d’unité 1 cm, A(1;2) et B(7;10). Calculer AB.",r"Les écarts horizontal et vertical valent 6 et 8. Dans le triangle rectangle construit, $AB^2=6^2+8^2=100$, d’où $\res{AB=10\text{ cm}}$.","Construire les deux déplacements perpendiculaires.","assert (7-1)**2+(10-2)**2==100",figure='pyth-repere'),
P(10,'Un angle à identifier',r"AB = 10 cm, AC = 6 cm et BC = 8 cm. Prouver que le triangle est rectangle et préciser où.",r"Le plus grand côté est AB. $AB^2=100=36+64=AC^2+BC^2$. La réciproque donne un angle droit $\res{\text{en C}}$, opposé à AB. La position du dessin ne détermine pas l’angle droit.","Nommer le sommet opposé à l’hypoténuse.","assert 6**2+8**2==10**2",('10 cm','6 cm','8 cm'),False),
P(11,'Une voile et son aire',r"Une voile ABC est rectangle en A. AB = 2,4 m et BC = 4 m. Calculer AC puis son aire.",r"$AC^2=16-5{,}76=10{,}24$, donc AC = 3,2 m. L’aire vaut $AB\times AC/2=2{,}4\times3{,}2/2=\res{3{,}84\text{ m}^2}$. On utilise les deux côtés perpendiculaires.","Enchaîner une longueur puis une aire.","assert Rational(4)**2-Rational('2.4')**2==Rational('3.2')**2 and Rational('2.4')*Rational('3.2')/2==Rational('3.84')",('2,4 m','?','4 m')),
P(12,'Passer un panneau',r"Une ouverture rectangulaire a pour côtés 0,9 m et 1,2 m. Sa diagonale BC est-elle assez longue pour une tige rigide de 1,48 m, d’épaisseur négligeable, placée dans le plan de l’ouverture ?",r"La diagonale vaut $\sqrt{0{,}9^2+1{,}2^2}=\res{1{,}5\text{ m}}$. Comme $1{,}48<1{,}5$, la tige peut être placée suivant cette diagonale dans le modèle proposé. L’épaisseur réelle pourrait imposer une marge.","Comparer des longueurs dans le même modèle.","assert Rational('.9')**2+Rational('1.2')**2==Rational('1.5')**2 and Rational('1.48')<Rational('1.5')",('1,2 m','0,9 m','?')),
P(13,'Une rampe',r"Une rampe BC monte de AC = 0,75 m sur une avancée horizontale AB = 10 m. Calculer la longueur de rampe au centimètre. La pente est définie ici par $100\,AC/AB$. Calculer cette pente.",r"$BC=\sqrt{10^2+0{,}75^2}\approx\res{10{,}03\text{ m}}$. La pente vaut $100\times0{,}75/10=\res{7{,}5\,\%}$. On ne divise pas la hauteur par la longueur inclinée dans cette définition.","Distinguer avancée horizontale et longueur inclinée.","assert round(math.sqrt(100+.75**2),2)==10.03 and Rational(100)*Rational('.75')/10==Rational('7.5')",('10 m','0,75 m','?')),
E('Deux chemins',r"Un parc rectangulaire mesure 120 m sur 160 m. On compare le trajet suivant deux côtés adjacents au trajet diagonal. Quelle distance économise-t-on ?",r"Le trajet par les côtés vaut 280 m. La diagonale vaut $\sqrt{120^2+160^2}=200$ m. L’économie est $\res{80\text{ m}}$, soit $80/280=2/7$ du trajet initial, environ 28,6 \%.","Comparer les trajets après les avoir calculés.","assert 120**2+160**2==200**2 and 120+160-200==80",figure='pyth-parc'),
E('Une hauteur de triangle',r"ABC est isocèle en C : CA = CB = 13 cm et AB = 10 cm. H est le milieu de AB. Calculer CH puis l’aire de ABC.",r"Dans un triangle isocèle, la médiane CH est aussi une hauteur. AH = 5 cm et ACH est rectangle en H. $CH^2=13^2-5^2=144$, donc CH = 12 cm. L’aire vaut $10\times12/2=\res{60\text{ cm}^2}$.","Justifier la perpendicularité avant Pythagore.","assert 13**2-5**2==12**2 and 10*12/2==60",figure='pyth-iso')
],reperes=['Calculer une longueur avec Pythagore','Réciproque et contraposée','Distances dans un repère orthonormé','Problèmes de longueurs et d’aires'],deco='geometrie')

def T(i,titre,enonce,corrige,methode,controle,ratio=.6,papillon=False,labels=()):
    if papillon:
        pts={'A':(0,0),'B':(5,0),'C':(2,3),'M':(-5*ratio,0),'N':(-2*ratio,-3*ratio)}
    else: pts={'A':(0,0),'B':(5,0),'C':(2,3),'M':(5*ratio,0),'N':(2*ratio,3*ratio)}
    fig=schema(f'thales-{i:02}',pts,[('A','B'),('B','C'),('C','A'),('A','M'),('A','N'),('M','N')],labels)
    return E(titre,enonce,corrige,methode,controle,figure=fig)

chapitre(13,'thales','Thalès et triangles semblables','4 · Géométrie',
'Alignements · Parallèles · Réciproque · Échelles',
['Écrire les rapports de côtés correspondants.','Calculer et démontrer un parallélisme.','Reconnaître et utiliser des triangles semblables.'],['Proportionnalité, fractions et produits en croix.'],[
r'''\essSection{1}{Le théorème de Thalès}
\begin{propriete}Si A, M, B sont alignés, A, N, C sont alignés et $(MN)\parallel(BC)$, dans les configurations emboîtée ou en papillon, alors $\dfrac{AM}{AB}=\dfrac{AN}{AC}=\dfrac{MN}{BC}$. Les longueurs utilisées sont positives.\end{propriete}
\begin{savoirfaire}[Associer les côtés]Dans les triangles AMN et ABC, A correspond à A, M à B et N à C. Tous les numérateurs doivent appartenir au même triangle. Choisir ensuite le rapport contenant l’inconnue et des données connues.\end{savoirfaire}
\begin{exemple}Si $AM=3$, $AB=5$, $AC=7$ et les hypothèses sont vérifiées, $AN/7=3/5$, donc $AN=4{,}2$ dans la même unité.\end{exemple}
\begin{attention}Si M est entre A et B, $MB=AB-AM$. Dans une configuration en papillon, où A est entre M et B, $MB=AM+AB$. Lire l’ordre des points avant de calculer.\end{attention}''',
r'''\essSection{2}{Réciproque et similitude}
\begin{propriete}[Réciproque de Thalès]Si A, M, B et A, N, C sont alignés dans le même ordre et si $AM/AB=AN/AC$, alors $(MN)\parallel(BC)$. Préciser les alignements et l’ordre avant de comparer les rapports.\end{propriete}
\begin{propriete}Si les alignements sont connus et si ces rapports diffèrent, les droites ne sont pas parallèles : sinon le théorème imposerait leur égalité.\end{propriete}
\begin{definition}Deux triangles sont semblables quand leurs angles sont égaux deux à deux. Deux angles égaux suffisent, car la somme des angles vaut $180^\circ$. Les côtés correspondants sont alors proportionnels.\end{definition}
\begin{propriete}Si le coefficient des longueurs est $k>0$, le rapport des périmètres est $k$ et celui des aires est $k^2$. Une correspondance erronée des sommets donne des rapports inutilisables.\end{propriete}
\begin{savoirfaire}[Rédiger]Énoncer les hypothèses, nommer le théorème, écrire l’égalité des rapports puis calculer. Dans une réciproque, conclure explicitement au parallélisme des deux droites nommées.\end{savoirfaire}'''],[
T(1,'Écrire les rapports',r"Dans la figure, M appartient à [AB], N à [AC] et $(MN)\parallel(BC)$. Écrire les rapports égaux.",r"Les alignements et le parallélisme permettent Thalès : $\res{AM/AB=AN/AC=MN/BC}$. Les petits côtés sont tous au numérateur.","Garder la même correspondance des sommets.","assert Rational(3,5)==Rational(6,10)"),
T(2,'Une longueur réduite',r"M est sur [AB], N sur [AC] et $(MN)\parallel(BC)$. AM = 3 cm, AB = 5 cm, AC = 10 cm. Calculer AN.",r"Thalès donne $AN/10=3/5$. Ainsi $\res{AN=6\text{ cm}}$. Cette longueur est inférieure à AC, conformément à l’emboîtement.","Multiplier la grande longueur par le rapport de réduction.","assert 10*Rational(3,5)==6"),
T(3,'La petite base',r"Dans la même configuration parallèle, AM = 4 cm, AB = 10 cm et BC = 15 cm. Calculer MN.",r"$MN/15=4/10$, donc $\res{MN=6\text{ cm}}$. Le rapport des longueurs est 0,4.","Choisir le rapport portant l’inconnue.","assert 15*Rational(4,10)==6",ratio=.4),
T(4,'Retrouver le grand côté',r"M est sur [AB], N sur [AC], $(MN)\parallel(BC)$. AM = 6 cm, AN = 4 cm et AC = 10 cm. Calculer AB.",r"$6/AB=4/10$. Le produit en croix donne $4AB=60$, donc $\res{AB=15\text{ cm}}$.","Une longueur agrandie se trouve en divisant par le rapport.","assert 6/Rational(4,10)==15",ratio=.4),
T(5,'De la partie au tout',r"M est sur [AB], N sur [AC], $(MN)\parallel(BC)$. AM = 3 cm, MB = 2 cm et AC = 12 cm. Calculer AN.",r"Comme M est entre A et B, AB = 3 + 2 = 5 cm. Puis $AN=12\times3/5=\res{7{,}2\text{ cm}}$. Employer MB au dénominateur aurait associé les mauvais côtés.","Reconstituer le côté entier avant Thalès.","assert 12*Rational(3,3+2)==Rational('7.2')"),
T(6,'Démontrer un parallélisme',r"A, M, B sont alignés dans cet ordre ; A, N, C aussi. AM = 4, AB = 10, AN = 6 et AC = 15, en cm. Montrer que MN et BC sont parallèles.",r"$AM/AB=4/10=2/5$ et $AN/AC=6/15=2/5$. Les alignements et l’ordre sont donnés. La réciproque de Thalès donne $\res{(MN)\parallel(BC)}$.","Vérifier les conditions géométriques avant les rapports.","assert Rational(4,10)==Rational(6,15)",ratio=.4),
T(7,'Des droites non parallèles',r"A, M, B et A, N, C sont alignés dans cet ordre. AM = 3, AB = 8, AN = 5, AC = 12, en cm. Les droites MN et BC sont-elles parallèles ?",r"$3/8\ne5/12$, car $3\times12=36$ et $5\times8=40$. Si les droites étaient parallèles, Thalès imposerait l’égalité. Elles $\res{\text{ne sont pas parallèles}}$.","Comparer exactement, sans arrondir les quotients.","assert 3*12!=5*8"),
T(8,'Le papillon',r"M, A, B sont alignés dans cet ordre ; N, A, C aussi. $(MN)\parallel(BC)$, AM = 3 cm, AB = 5 cm et AC = 8 cm. Calculer AN.",r"Thalès s’applique aussi au papillon : $AN/8=3/5$. Donc $\res{AN=4{,}8\text{ cm}}$. Les longueurs ne deviennent pas négatives parce que les points changent de côté de A.","Conserver les longueurs positives dans les rapports.","assert 8*Rational(3,5)==Rational('4.8')",papillon=True),
T(9,'La distance entre deux points',r"Dans le papillon précédent, AM = 3 cm et AB = 5 cm. Calculer MB. Si AN = 4,8 cm et AC = 8 cm, calculer NC.",r"A est entre les points de chaque paire : $\res{MB=3+5=8\text{ cm}}$ et $\res{NC=4{,}8+8=12{,}8\text{ cm}}$. Une soustraction correspondrait à une autre disposition.","Lire l’ordre des points.","assert 3+5==8 and Rational('4.8')+8==Rational('12.8')",papillon=True),
E('Des angles correspondants',r"ABC et DEF ont respectivement les angles $(40^\circ,65^\circ,75^\circ)$ et $(65^\circ,75^\circ,40^\circ)$. Donner la correspondance des sommets. Si AB = 6 cm et FD = 9 cm, quel est le coefficient d’agrandissement ?",r"Les angles égaux donnent A vers F, B vers D, C vers E. AB correspond à FD : le coefficient vaut $9/6=\res{1{,}5}$. Les triangles sont semblables par leurs angles.","Associer les angles avant les côtés.","assert 40+65+75==180 and Rational(9,6)==Rational('1.5')",figure='semblables-angles'),
E('Une aire agrandie',r"Deux triangles semblables ont des côtés correspondants de 4 cm et 10 cm. L’aire du petit est 12 cm$^2$. Calculer le périmètre du grand si celui du petit est 15 cm, puis son aire.",r"Le coefficient vaut $10/4=2{,}5$. Le périmètre est $15\times2{,}5=\res{37{,}5\text{ cm}}$. L’aire est $12\times2{,}5^2=\res{75\text{ cm}^2}$. Les aires ne suivent pas le seul facteur des longueurs.","Élever le coefficient au carré pour les aires.","assert 15*Rational(5,2)==Rational('37.5') and 12*Rational(5,2)**2==75",figure='semblables-aires'),
E('L’ombre d’un arbre',r"Un bâton vertical de 1,5 m projette une ombre de 2 m. Au même instant, un arbre vertical projette une ombre de 12 m sur le même sol horizontal. Les rayons solaires sont parallèles. Calculer la hauteur de l’arbre.",r"Les triangles ont un angle droit et le même angle avec les rayons : ils sont semblables. Le rapport est $12/2=6$. La hauteur vaut $1{,}5\times6=\res9$ m. Les hypothèses de sol horizontal et de rayons parallèles justifient le modèle.","Identifier deux triangles semblables.","assert Rational('1.5')*12/2==9",figure='thales-ombre'),
T(13,'Une équation dans Thalès',r"M est sur [AB], N sur [AC], MN est parallèle à BC. AM = 4 cm, MB = $x$ cm, AN = 6 cm et NC = 3 cm. Trouver $x$.",r"AB = $4+x$ et AC = 9. Thalès donne $4/(4+x)=6/9=2/3$. Ainsi $12=8+2x$, donc $\res{x=2\text{ cm}}$. La valeur est positive et redonne $4/6=6/9$.","Exprimer les côtés entiers avant de résoudre.","assert solve(12-2*(4+x),x)==[2]"),
E('Calculer une largeur inaccessible',r"A, B, C forment un triangle. M est le milieu de AB et N le milieu de AC ; BC traverse une zone inaccessible. On mesure MN = 7,4 m. Justifier le parallélisme puis calculer BC.",r"Les milieux donnent $AM/AB=AN/AC=1/2$ avec le même ordre. La réciproque de Thalès donne le parallélisme. Puis $MN/BC=1/2$, donc $\res{BC=14{,}8\text{ m}}$.","Séparer la preuve du parallélisme et le calcul.","assert Rational('7.4')*2==Rational('14.8')",figure='thales-milieux'),
T(15,'Un contrôle critique',r"Dans une configuration emboîtée avec MN parallèle à BC, un élève écrit $AM/AB=NC/AC$. AM = 3 cm, AB = 8 cm, AC = 16 cm. Corriger et calculer NC.",r"AM correspond à AN, donc $AN/16=3/8$, d’où AN = 6 cm. Puis $NC=16-6=\res{10\text{ cm}}$. NC n’est pas un côté du petit triangle AMN.","Vérifier que chaque terme est un côté correspondant.","assert 16*Rational(3,8)==6 and 16-6==10",ratio=.375)
],reperes=['Thalès emboîté et en papillon','Réciproque et non-parallélisme','Triangles semblables et correspondances','Rapports des longueurs, périmètres et aires'],deco='geometrie')
